import "container/list"

// LRU is a fixed-capacity least-recently-used cache.
type LRU struct {
	capacity int
	items    map[string]*list.Element
	ll       *list.List
}

// entry is the value stored in the linked list element.
type entry struct {
	key   string
	value int
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		ll:       list.New(),
	}
}

// Get returns the value for key and marks it as most recently used.
// If the key is not present, it returns zero and false.
func (c *LRU) Get(key string) (int, bool) {
	el, ok := c.items[key]
	if !ok {
		return 0, false
	}
	// Move to front (most recently used).
	c.ll.MoveToFront(el)
	return el.Value.(*entry).value, true
}

// Put inserts or updates key with value.
// Updating an existing key does not grow the cache.
// When the cache is full, the least recently used entry is evicted.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	if el, ok := c.items[key]; ok {
		// Update existing entry and mark as most recently used.
		el.Value.(*entry).value = value
		c.ll.MoveToFront(el)
		return
	}

	// Evict least recently used if at capacity.
	if len(c.items) >= c.capacity {
		oldest := c.ll.Back()
		if oldest != nil {
			c.ll.Remove(oldest)
			delete(c.items, oldest.Value.(*entry).key)
		}
	}

	// Insert new entry at front (most recently used).
	el := c.ll.PushFront(&entry{key: key, value: value})
	c.items[key] = el
}

// Len returns the number of entries currently stored in the cache.
func (c *LRU) Len() int {
	return len(c.items)
}

